    ok = ok && g.sheriffState == 2 && g.enflameWaits == 1 && std::strcmp(g.lastLine, "TEXT_QST_B07_SHERIFF_HERO_SUSSED") == 0 && g.pauseDepth == 0;
    if (!ok) {
